"""Regression tests for inert shell code generated by pass-insert-utility."""
from pathlib import Path
import shutil
import subprocess
import tempfile
import unittest


ROOT = Path(__file__).resolve().parents[1]
HELPER = ROOT / "scripts/.local/bin/pass-insert-utility"


class PassInsertCodegenTests(unittest.TestCase):
    def setUp(self):
        self.temp = tempfile.TemporaryDirectory(prefix="pass-insert-codegen-")
        self.addCleanup(self.temp.cleanup)
        self.root = Path(self.temp.name)
        self.home = self.root / "home"
        self.home.mkdir()
        store = self.home / ".password-store"
        store.mkdir()
        (store / ".gpg-id").write_text("fixture-key")
        self.bin = self.root / "bin"
        self.bin.mkdir()
        for name in ("bash", "cat", "chmod", "grep", "tr"):
            (self.bin / name).symlink_to(shutil.which(name))
        self.env = {"HOME": str(self.home), "PATH": str(self.bin), "LC_ALL": "C"}
        self.script("pass", '''
if [[ "$1" == insert ]]; then
    exit 0
fi
if [[ "$1" == show ]]; then
    [[ "${PASS_FAIL:-0}" == 0 ]] || exit 7
    printf '%s\\n' "${PASS_VALUE:-fixture-secret}"
    exit 0
fi
exit 9
''')
        self.script("pwgen", "printf 'fixture-generated-password\\n'")

    def script(self, name, body):
        path = self.bin / name
        path.write_text("#!/bin/bash\nset -euo pipefail\n" + body + "\n")
        path.chmod(0o755)

    def run_helper(self, input_text):
        return subprocess.run([str(HELPER)], env=self.env, input=input_text,
                              capture_output=True, text=True, timeout=10)

    def test_hyphenated_export_name_is_rejected_without_appending(self):
        result = self.run_helper("ai\napi-key\nsecret\n")
        self.assertNotEqual(result.returncode, 0)
        self.assertIn("Invalid export variable name", result.stderr)
        load_file = self.home / "load-api-keys.sh"
        self.assertFalse(load_file.exists())

    def test_shell_syntax_in_pass_path_is_rejected_without_execution(self):
        sentinel = self.root / "sentinel"
        for category in (f"ai$(touch {sentinel})", f"ai`touch {sentinel}`", "ai;touch sentinel"):
            with self.subTest(category=category):
                result = self.run_helper(f"{category}\nvalid key\nsecret\n")
                self.assertNotEqual(result.returncode, 0)
                self.assertIn("Invalid pass path", result.stderr)
                self.assertFalse(sentinel.exists())
                self.assertFalse((self.home / "load-api-keys.sh").exists())

    def test_generated_literal_path_warns_on_pass_failure(self):
        result = self.run_helper("ai\nopenai api key\nsecret\n")
        self.assertEqual(result.returncode, 0, result.stdout + result.stderr)
        load_file = self.home / "load-api-keys.sh"
        generated = load_file.read_text()
        self.assertIn("pass show 'ai/openai_api_key'", generated)
        self.assertIn('export OPENAI_API_KEY="$value"', generated)
        self.assertIn("Warning: could not load ai/openai_api_key from pass", generated)
        self.assertNotIn("export OPENAI_API_KEY=$(", generated)

        env = dict(self.env, PASS_FAIL="1")
        sourced = subprocess.run(
            ["bash", "-c", 'unset OPENAI_API_KEY; source "$HOME/load-api-keys.sh"; '
             '[[ -z ${OPENAI_API_KEY+x} ]]'],
            env=env, capture_output=True, text=True, timeout=10,
        )
        self.assertEqual(sourced.returncode, 0, sourced.stdout + sourced.stderr)
        self.assertIn("Warning: could not load", sourced.stderr)

    def test_valid_insert_writes_parseable_block(self):
        result = self.run_helper("ai\nopenai api key\nsecret\n")
        self.assertEqual(result.returncode, 0, result.stdout + result.stderr)
        generated = (self.home / "load-api-keys.sh").read_text()
        parsed = subprocess.run(["bash", "-n"], input=generated, text=True,
                                capture_output=True, timeout=10)
        self.assertEqual(parsed.returncode, 0, parsed.stderr)
        self.assertIn("export OPENAI_API_KEY=", generated)
        self.assertIn("pass show 'ai/openai_api_key'", generated)

    def test_duplicate_insert_is_skipped(self):
        for _ in range(2):
            result = self.run_helper("ai\nopenai api key\nsecret\n")
            self.assertEqual(result.returncode, 0, result.stdout + result.stderr)
        generated = (self.home / "load-api-keys.sh").read_text()
        self.assertEqual(generated.count("pass show 'ai/openai_api_key'"), 1)


if __name__ == "__main__":
    unittest.main()
